"""
restore.py - Recreates all bot files from base64.
Run: python restore.py
"""
import base64, os

FILES = {
    'bot/config.py': '',
    'bot/main.py': '',
    'bot/setup_api_key.py': '',
    'bot/test_api.py': '',
    'bot/test_setup.py': '',
    'bot/feeds/__init__.py': '',
    'bot/feeds/binance_ws.py': '',
    'bot/strategy/__init__.py': '',
    'bot/strategy/signal_engine.py': '',
    'bot/polymarket/__init__.py': '',
    'bot/polymarket/api_client.py': '',
    'bot/polymarket/market_scanner.py': '',
    'bot/polymarket/simulated_contracts.py': '',
    'bot/utils/__init__.py': '',
    'bot/utils/dashboard.py': '',
    'bot/utils/database.py': '',
    'bot/risk/__init__.py': '',
    'bot/risk/risk_manager.py': '',
    'bot/execution/__init__.py': '',
    'bot/execution/live_engine.py': '',
    'bot/execution/paper_engine.py': '',
}

for path, b64 in FILES.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print("Restored:", path)
print("\nDONE")
